export const LANGUAGE_FALLBACKS = {
  ko: "en",
  es: "en",
  fr: "en",
  de: "en",
  pt: "en",
  th: "en",
  vi: "en",
  ru: "en",
};

export function getStoredLanguage() {
  if (typeof window === "undefined") {
    return "";
  }

  try {
    const stored = window.localStorage.getItem(LANGUAGE_STORAGE_KEY);
    return APP_LANGUAGES.some((language) => language.id === stored) ? stored : "";
  } catch {
    return "";
  }
}

export function getCopyLanguage(languageId) {
  return UI_COPY[languageId] ? languageId : LANGUAGE_FALLBACKS[languageId] ?? "en";
}

export function createTranslator(languageId) {
  const copyLanguage = getCopyLanguage(languageId);
  const copy = UI_COPY[copyLanguage] ?? UI_COPY.en;
  const fallback = UI_COPY.en;
  const srtImportCopy = SRT_IMPORT_COPY[languageId] ?? SRT_IMPORT_COPY.en;
  const exportCopy = EXPORT_RENDER_COPY[copyLanguage] ?? EXPORT_RENDER_COPY.en;
  const exportOptionsCopy = EXPORT_OPTIONS_COPY[languageId] ?? EXPORT_OPTIONS_COPY.en;
  const exportExtraStatusCopy = EXPORT_EXTRA_STATUS_COPY[languageId] ?? EXPORT_EXTRA_STATUS_COPY.en;
  const assetPreviewCopy = ASSET_PREVIEW_COPY[copyLanguage] ?? ASSET_PREVIEW_COPY.en;
  const assetDropCopy = ASSET_DROP_COPY[copyLanguage] ?? ASSET_DROP_COPY.en;
  const autoCaptionStatusCopy = AUTO_CAPTION_STATUS_COPY[copyLanguage] ?? AUTO_CAPTION_STATUS_COPY.en;
  const ttsBackendCopy = TTS_BACKEND_COPY[languageId] ?? TTS_BACKEND_COPY[copyLanguage] ?? TTS_BACKEND_COPY.en;
  const captionAudioLinkCopy = CAPTION_AUDIO_LINK_COPY[languageId] ?? CAPTION_AUDIO_LINK_COPY[copyLanguage] ?? CAPTION_AUDIO_LINK_COPY.en;
  const mobileDrawerCopy = MOBILE_DRAWER_COPY[languageId] ?? MOBILE_DRAWER_COPY.en;
  const mobileClipActionCopy = MOBILE_CLIP_ACTION_COPY[languageId] ?? MOBILE_CLIP_ACTION_COPY.en;
  const mobileStickerCopy = MOBILE_STICKER_COPY[languageId] ?? MOBILE_STICKER_COPY.en;
  const completionCopy = globalThis.__GENERATING_I18N__ ? {} : I18N_COMPLETION_COPY[languageId] ?? I18N_COMPLETION_COPY.en ?? {};
  const repairCopy = { ...REPAIR_COPY.en, ...(REPAIR_COPY[languageId] ?? {}), ...(REPAIR_LOCALIZED_COPY[languageId] ?? {}), ...(DENOISE_LOCALIZED_COPY[languageId] ?? DENOISE_LOCALIZED_COPY.en), ...(DENOISE_HUB_HINT_COPY[languageId] ?? DENOISE_HUB_HINT_COPY.en) };
  const projectChromeCopy = PROJECT_CHROME_COPY[languageId] ?? PROJECT_CHROME_COPY.en;
  const coreLabelCopy = CORE_LABEL_COPY[languageId] ?? CORE_LABEL_COPY.en;
  const specializedCopy = Object.assign({}, ...[
    EXPORT_RENDER_COPY, MEDIA_COMPATIBILITY_COPY, COMMUNITY_LINKS_COPY, AUDIO_SPATIAL_COPY, VOICE_COLOR_COPY, VOICE_CLONE_COPY, TIMELINE_SELECTION_COPY, TIMELINE_FINE_EDIT_COPY, TIMELINE_TRIM_COPY, TIMELINE_TOOLBAR_COPY, SHORTCUT_GUIDE_COPY, FACE_SWAP_COPY, VECTOR_LIBRARY_COPY, PROJECT_CHROME_COPY, CORE_LABEL_COPY, MOBILE_DRAWER_COPY, MOBILE_CLIP_ACTION_COPY, PLUGIN_TOOL_COPY,
    VISUAL_EDITOR_COPY, COLOR_GRADE_COPY, TRANSITION_EDITOR_COPY, ASSET_PREVIEW_COPY, ASSET_DROP_COPY,
    AUTO_CAPTION_STATUS_COPY, VISUAL_PANEL_TITLE_COPY, VISUAL_MASK_SHAPE_COPY,
    VISUAL_KEYFRAME_ACTION_COPY, VISUAL_TAB_COPY, VISUAL_SPEED_CURVE_COPY, SOURCE_AUDIO_SYNC_COPY,
    CAPTION_WORKSPACE_COPY, RESOURCE_LINK_COPY, VISUAL_AI_TAB_COPY, REPAIR_COPY, REMASTER_COPY,
    REMASTER_CLIP_COPY, REMASTER_GPU_COPY, REMASTER_PHASE_COPY, CONTEXT_PANEL_COPY,
    TIMELINE_AUDIO_MENU_COPY, SOURCE_AUDIO_LANE_COPY, TTS_BACKEND_COPY, CAPTION_AUDIO_LINK_COPY,
    VISUAL_ANIMATION_COPY, STICKER_EDITOR_COPY, MOBILE_STICKER_COPY,
    CAPTION_DEFAULT_COPY, SMART_WORKSPACE_COPY, AUTO_EDIT_COPY, AUTO_EDIT_BUTTON_COPY, AUTO_EDIT_READY_COPY,
    AUTO_EDIT_REVIEW_COPY, AUTO_EDIT_FLOW_COPY, AUTO_EDIT_SEGMENT_COPY,
    AUTO_EDIT_RESULT_COPY, IMAGE_AI_CAPTION_COPY, PICTURE_IN_PICTURE_COPY, EFFECTS_WORKSPACE_COPY, VECTOR_STATE_COPY, VECTOR_DOCUMENT_COPY, VECTOR_ADVANCED_COPY,
    SRT_IMPORT_COPY, CLICK_RIPPLE_COPY,
  ].map((source) => source[languageId] ?? {}));
  return (key, fallbackText) => coreLabelCopy[key] ?? repairCopy[key] ?? specializedCopy[key] ?? exportOptionsCopy[key] ?? EXPORT_OPTIONS_COPY.en[key] ?? exportExtraStatusCopy[key] ?? EXPORT_EXTRA_STATUS_COPY.en[key] ?? projectChromeCopy[key] ?? PROJECT_CHROME_COPY.en[key] ?? captionAudioLinkCopy[key] ?? CAPTION_AUDIO_LINK_COPY.en[key] ?? ttsBackendCopy[key] ?? TTS_BACKEND_COPY.en[key] ?? mobileStickerCopy[key] ?? MOBILE_STICKER_COPY.en[key] ?? mobileClipActionCopy[key] ?? MOBILE_CLIP_ACTION_COPY.en[key] ?? mobileDrawerCopy[key] ?? MOBILE_DRAWER_COPY.en[key] ?? srtImportCopy[key] ?? exportCopy[key] ?? EXPORT_RENDER_COPY.en[key] ?? assetPreviewCopy[key] ?? ASSET_PREVIEW_COPY.en[key] ?? assetDropCopy[key] ?? ASSET_DROP_COPY.en[key] ?? autoCaptionStatusCopy[key] ?? AUTO_CAPTION_STATUS_COPY.en[key] ?? completionCopy[key] ?? copy[key] ?? fallback[key] ?? UI_COPY.zh[key] ?? fallbackText ?? key;
}

export function translateOptionName(languageId, name) {
  const copyLanguage = getCopyLanguage(languageId);
  return OPTION_COPY[copyLanguage]?.[name] ?? OPTION_COPY.en?.[name] ?? name;
}

export function saveLanguagePreference(languageId) {
  try {
    window.localStorage.setItem(LANGUAGE_STORAGE_KEY, languageId);
  } catch {
    // localStorage may be unavailable in private browsing; keep the in-memory language.
  }
}
